import fs from "node:fs";

// CLI keeps its existing eight-image allowance; IDE composers admit four.
export const MAX_INPUT_IMAGES = 8;
export const MAX_INPUT_IMAGE_BYTES = 20 * 1024 * 1024;
export const MAX_INPUT_IMAGE_PIXELS = 40_000_000;
const MAX_HEADER_BYTES = 1024 * 1024;

/** Header admission only, not a full codec decode or animation-frame budget. */
export function inspectImageHeader(data) {
  const ascii = (start, end) => data.toString("ascii", start, end);
  if (
    data.length >= 33 &&
    data
      .subarray(0, 8)
      .equals(Buffer.from([137, 80, 78, 71, 13, 10, 26, 10])) &&
    data.readUInt32BE(8) === 13 &&
    ascii(12, 16) === "IHDR"
  ) {
    return {
      mediaType: "image/png",
      width: data.readUInt32BE(16),
      height: data.readUInt32BE(20),
    };
  }
  if (data.length >= 13 && ["GIF87a", "GIF89a"].includes(ascii(0, 6))) {
    return {
      mediaType: "image/gif",
      width: data.readUInt16LE(6),
      height: data.readUInt16LE(8),
    };
  }
  if (data.length >= 30 && ascii(0, 4) === "RIFF" && ascii(8, 12) === "WEBP") {
    const kind = ascii(12, 16);
    if (kind === "VP8X")
      return {
        mediaType: "image/webp",
        width: data.readUIntLE(24, 3) + 1,
        height: data.readUIntLE(27, 3) + 1,
      };
    if (
      kind === "VP8 " &&
      data[23] === 157 &&
      data[24] === 1 &&
      data[25] === 42
    )
      return {
        mediaType: "image/webp",
        width: data.readUInt16LE(26) & 16383,
        height: data.readUInt16LE(28) & 16383,
      };
    if (kind === "VP8L" && data[20] === 47) {
      const bits = data.readUInt32LE(21);
      return {
        mediaType: "image/webp",
        width: (bits & 16383) + 1,
        height: ((bits >>> 14) & 16383) + 1,
      };
    }
  }
  if (data.length >= 4 && data[0] === 255 && data[1] === 216) {
    let offset = 2;
    while (offset + 4 <= data.length) {
      if (data[offset++] !== 255) break;
      while (data[offset] === 255) offset++;
      const marker = data[offset++];
      if (marker === 217 || marker === 218) break;
      if (marker === 1 || (marker >= 208 && marker <= 215)) continue;
      if (offset + 2 > data.length) break;
      const length = data.readUInt16BE(offset);
      if (length < 2 || offset + length > data.length) break;
      if (
        [
          192, 193, 194, 195, 197, 198, 199, 201, 202, 203, 205, 206, 207,
        ].includes(marker) &&
        length >= 8
      ) {
        return {
          mediaType: "image/jpeg",
          width: data.readUInt16BE(offset + 5),
          height: data.readUInt16BE(offset + 3),
        };
      }
      offset += length;
    }
  }
  throw new Error(
    "Unsupported or malformed image header (dimensions must occur within the first 1 MiB)",
  );
}

function readAtMost(io, fd, data) {
  let offset = 0;
  while (offset < data.length) {
    const count = io.readSync(fd, data, offset, data.length - offset, offset);
    if (count === 0) break;
    offset += count;
  }
  return offset;
}

/** Pin one regular-file descriptor and cap allocation/read even if it grows. */
export function readBoundedImage(
  file,
  expectedMediaType,
  remainingBytes,
  io = fs,
) {
  // O_NONBLOCK avoids hanging while opening a FIFO on POSIX. fstat then
  // rejects all non-regular files; Windows has no O_NONBLOCK flag here.
  const fd = io.openSync(
    file,
    fs.constants.O_RDONLY | (fs.constants.O_NONBLOCK || 0),
  );
  try {
    const before = io.fstatSync(fd);
    if (!before.isFile()) throw new Error("Image input must be a regular file");
    if (
      !Number.isSafeInteger(before.size) ||
      before.size <= 0 ||
      before.size > MAX_INPUT_IMAGE_BYTES
    )
      throw new Error("Image must contain 1 byte to 20 MiB");
    if (before.size > remainingBytes)
      throw new Error("Total image attachments exceed 20 MiB per message");
    const header = Buffer.alloc(Math.min(before.size, MAX_HEADER_BYTES));
    const headerSize = readAtMost(io, fd, header);
    const info = inspectImageHeader(header.subarray(0, headerSize));
    if (info.mediaType !== expectedMediaType)
      throw new Error("Image extension does not match its file header");
    if (
      !info.width ||
      !info.height ||
      info.width * info.height > MAX_INPUT_IMAGE_PIXELS
    )
      throw new Error(
        "Image dimensions must be positive and at most 40 megapixels",
      );
    const data = Buffer.alloc(before.size + 1);
    const count = readAtMost(io, fd, data);
    const after = io.fstatSync(fd);
    if (
      count !== before.size ||
      after.size !== before.size ||
      after.mtimeMs !== before.mtimeMs ||
      after.ctimeMs !== before.ctimeMs ||
      !data.subarray(0, headerSize).equals(header.subarray(0, headerSize))
    )
      throw new Error("Image changed while being read; select it again");
    return data.subarray(0, count);
  } finally {
    io.closeSync(fd);
  }
}

import { afterAll, describe, expect, it, vi } from "vitest";
import fs from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { resolveImages } from "../../src/lib/image-input.js";
import {
  inspectImageHeader,
  MAX_INPUT_IMAGE_BYTES,
} from "../../src/lib/image-file-boundary.js";
import {
  PNG_BYTES,
  imageHeader,
  imageFsFixture,
} from "../helpers/image-file-fixtures.js";

const root = fs.mkdtempSync(join(tmpdir(), "cc-image-boundary-"));
afterAll(() => fs.rmSync(root, { recursive: true, force: true }));
function file(name, data = PNG_BYTES, size) {
  const target = join(root, name);
  fs.writeFileSync(target, data);
  if (size) fs.truncateSync(target, size);
  return target;
}

describe("CLI final image input boundary", () => {
  it.each(["png", "jpeg", "gif", "webp"])(
    "recognizes bounded %s headers",
    (format) => {
      expect(inspectImageHeader(imageHeader(format))).toMatchObject({
        mediaType: `image/${format}`,
      });
      expect(
        resolveImages([file(`valid.${format}`, imageHeader(format))])[0]
          .mediaType,
      ).toBe(`image/${format}`);
    },
  );

  it("rejects a forged extension and malformed header before returning content", () => {
    expect(() => resolveImages([file("mismatch.jpg")])).toThrow(
      /extension does not match/,
    );
    expect(() =>
      resolveImages([file("invalid.png", Buffer.from("not an image"))]),
    ).toThrow(/malformed image header/);
    expect(() => resolveImages([file("empty.png", Buffer.alloc(0))])).toThrow(
      /1 byte to 20 MiB/,
    );
  });

  it("rejects zero and oversized pixel declarations", () => {
    for (const width of [0, 40_000_001]) {
      const bytes = Buffer.from(PNG_BYTES);
      bytes.writeUInt32BE(width, 16);
      expect(() => resolveImages([file(`pixel-${width}.png`, bytes)])).toThrow(
        /40 megapixels/,
      );
    }
  });

  it("bounds file size before any read or full-buffer allocation", () => {
    const target = file("oversized.png", PNG_BYTES, MAX_INPUT_IMAGE_BYTES + 1);
    const readSync = vi.fn(fs.readSync);
    const closeSync = vi.fn(fs.closeSync);
    expect(() =>
      resolveImages([target], { fs: { ...fs, readSync, closeSync } }),
    ).toThrow(/20 MiB/);
    expect(readSync).not.toHaveBeenCalled();
    expect(closeSync).toHaveBeenCalledOnce();
  });

  it("bounds the combined attachment bytes and identifies the failing entry", () => {
    const a = file("total-a.png", PNG_BYTES, 11 * 1024 * 1024);
    const b = file("total-b.png", PNG_BYTES, 11 * 1024 * 1024);
    expect(() => resolveImages([a, b])).toThrow(
      /Image 2: Total image attachments exceed 20 MiB/,
    );
  });

  it("rejects excess image count before opening files", () => {
    const openSync = vi.fn();
    expect(() =>
      resolveImages(Array(9).fill("same.png"), { fs: { openSync } }),
    ).toThrow(/at most 8/);
    expect(openSync).not.toHaveBeenCalled();
  });

  it("rejects non-regular handles and closes them", () => {
    const io = imageFsFixture();
    io.fstatSync = () => ({ isFile: () => false });
    io.closeSync = vi.fn();
    io.readSync = vi.fn();
    expect(() => resolveImages(["pipe.png"], { fs: io })).toThrow(
      /regular file/,
    );
    expect(io.readSync).not.toHaveBeenCalled();
    expect(io.closeSync).toHaveBeenCalledOnce();
  });

  it("uses bounded descriptor reads when the file grows after its size check", () => {
    const target = file("growing.png");
    let changed = false;
    const readSync = vi.fn((...args) => {
      const read = fs.readSync(...args);
      if (!changed) {
        changed = true;
        fs.appendFileSync(target, Buffer.alloc(1024));
      }
      return read;
    });
    const closeSync = vi.fn(fs.closeSync);
    expect(() =>
      resolveImages([target], { fs: { ...fs, readSync, closeSync } }),
    ).toThrow(/changed while being read/);
    expect(
      readSync.mock.calls.every((args) => args[3] <= PNG_BYTES.length + 1),
    ).toBe(true);
    expect(closeSync).toHaveBeenCalledOnce();
  });

  it.each(["mtimeMs", "ctimeMs"])(
    "rejects a same-size image whose pinned handle %s changes",
    (field) => {
      const io = imageFsFixture();
      let stats = 0;
      const baseStat = io.fstatSync;
      io.fstatSync = vi.fn((fd) => ({
        ...baseStat(fd),
        [field]: ++stats === 1 ? 1 : 2,
      }));
      io.closeSync = vi.fn();
      // The bytes, header, size and handle remain identical. Only the metadata
      // transition distinguishes this raced input from the valid control.
      expect(() => resolveImages(["stable.png"], { fs: io })).toThrow(
        /changed while being read/,
      );
      expect(io.fstatSync).toHaveBeenCalledTimes(2);
      expect(io.closeSync).toHaveBeenCalledOnce();
      const valid = imageFsFixture();
      expect(resolveImages(["stable.png"], { fs: valid })[0].data).toBe(
        PNG_BYTES.toString("base64"),
      );
    },
  );

  it("supports short reads and rejects a truncated file", () => {
    const target = file("short-read.png");
    const readSync = (fd, data, offset, length, position) =>
      fs.readSync(fd, data, offset, Math.min(length, 7), position);
    expect(resolveImages([target], { fs: { ...fs, readSync } })[0].data).toBe(
      PNG_BYTES.toString("base64"),
    );
    let reads = 0;
    const truncated = (...args) => (++reads === 1 ? fs.readSync(...args) : 0);
    expect(() =>
      resolveImages([target], { fs: { ...fs, readSync: truncated } }),
    ).toThrow(/changed while being read/);
  });

  it("caps JPEG header scanning at 1 MiB", () => {
    const segment = Buffer.alloc(65537);
    segment[0] = 255;
    segment[1] = 224;
    segment.writeUInt16BE(65535, 2);
    const data = Buffer.concat([
      Buffer.from([255, 216]),
      ...Array(17).fill(segment),
      imageHeader("jpeg").subarray(2),
    ]);
    expect(() => resolveImages([file("late-dimensions.jpg", data)])).toThrow(
      /first 1 MiB/,
    );
  });
});

import { afterEach, describe, expect, it, vi } from "vitest";
import fs from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
// From packages/cli/__tests__, ../src resolves to packages/cli/src.
import { readBoundedImage } from "../src/lib/image-file-boundary.js";

const BYTE_LIMIT = 20 * 1024 * 1024;
const HEADER_LIMIT = 1024 * 1024;
const roots = [];
afterEach(() => {
  for (const root of roots.splice(0)) {
    fs.rmSync(root, { recursive: true, force: true });
  }
});

function png(width = 1, height = 1) {
  // A complete 1x1 PNG; this API admits headers, not full codec decoding.
  const data = Buffer.from(
    "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+jRZkAAAAASUVORK5CYII=",
    "base64",
  );
  data.writeUInt32BE(width, 16);
  data.writeUInt32BE(height, 20);
  return data;
}

function fixture(data = png(), size = data.length) {
  const root = fs.mkdtempSync(join(tmpdir(), "repair137-handle-"));
  roots.push(root);
  const path = join(root, "input.png");
  fs.writeFileSync(path, data);
  fs.truncateSync(path, size);
  const io = {
    openSync: vi.fn((...args) => fs.openSync(...args)),
    fstatSync: vi.fn((...args) => fs.fstatSync(...args)),
    readSync: vi.fn((...args) => fs.readSync(...args)),
    closeSync: vi.fn((...args) => fs.closeSync(...args)),
  };
  return { path, io, data };
}

function read(f, budget = BYTE_LIMIT, type = "image/png") {
  return readBoundedImage(f.path, type, budget, f.io);
}

function closed(f) {
  expect(f.io.openSync).toHaveBeenCalledTimes(1);
  const fd = f.io.openSync.mock.results[0].value;
  expect(f.io.openSync.mock.calls[0]).toEqual([
    f.path,
    fs.constants.O_RDONLY | (fs.constants.O_NONBLOCK || 0),
  ]);
  for (const call of [...f.io.fstatSync.mock.calls, ...f.io.readSync.mock.calls]) {
    expect(call[0]).toBe(fd);
  }
  expect(f.io.closeSync.mock.calls).toEqual([[fd]]);
  expect(() => fs.fstatSync(fd)).toThrow(expect.objectContaining({ code: "EBADF" }));
}

// Mutate immediately before the body pass, after the header has been admitted.
// Pin metadata deliberately: each negative control isolates the named guard.
function beforeBody(f, change) {
  const original = fs.statSync(f.path);
  f.io.fstatSync.mockImplementation(() => original);
  let starts = 0;
  f.io.readSync.mockImplementation((fd, buffer, offset, length, position) => {
    if (position === 0 && ++starts === 2) change(fd);
    return fs.readSync(fd, buffer, offset, length, position);
  });
}

// Put a complete SOF segment exactly at the header window's end (or one
// byte beyond it). APP segments remain well formed in both controls.
function jpegAtHeaderEnd(extra) {
  const sof = Buffer.from([255, 192, 0, 8, 8, 0, 1, 0, 1, 0]);
  const parts = [Buffer.from([255, 216])];
  let padding = HEADER_LIMIT + extra - 2 - sof.length;
  while (padding > 0) {
    const size = Math.min(padding, 65537);
    const segment = Buffer.alloc(size);
    segment[0] = 255;
    segment[1] = 224;
    segment.writeUInt16BE(size - 2, 2);
    parts.push(segment);
    padding -= size;
  }
  return Buffer.concat([...parts, sof]);
}

// Coverage audit (all calls enter the real readBoundedImage):
// - size/budget/pixels/header-window: accepted upper boundary and next value;
// - width/height: 1 versus 0; type/signature/isFile: only that input differs;
// - replacement/count/final-stat races: unchanged control versus one change.
//   Metadata is pinned for byte/count races; bytes remain intact for stat races.
// - every opened descriptor is checked for same-handle use and actual closure.
// Not selected: invalid/empty initial stat sizes, other codec parser branches,
// open/read/close syscall failures, and mutations beyond the inspected header
// whose size and timestamps also remain unchanged (not promised by this API).

describe("independent admission controls", () => {
  it("accepts exactly 20 MiB and rejects the next byte before reading", () => {
    const expected = Buffer.alloc(BYTE_LIMIT);
    png().copy(expected);
    const valid = fixture(expected);
    const result = read(valid, BYTE_LIMIT + 1);
    expect(result.length).toBe(BYTE_LIMIT);
    expect(result.equals(expected)).toBe(true);
    closed(valid);

    // Sparse oversized input; no large negative-control body is allocated.
    const invalid = fixture(png(), BYTE_LIMIT + 1);
    expect(() => read(invalid, BYTE_LIMIT + 1)).toThrow(/1 byte to 20 MiB/);
    expect(invalid.io.readSync).not.toHaveBeenCalled();
    closed(invalid);
  });

  it("accepts exactly the remaining budget and rejects one byte beyond it", () => {
    const valid = fixture();
    expect(read(valid, valid.data.length).equals(valid.data)).toBe(true);
    closed(valid);
    const invalid = fixture();
    expect(() => read(invalid, invalid.data.length - 1)).toThrow(
      /Total image attachments exceed 20 MiB/,
    );
    expect(invalid.io.readSync).not.toHaveBeenCalled();
    closed(invalid);
  });

  it.each([
    ["pixel cap", [40_000_000, 1], [40_000_001, 1]],
    ["positive width", [1, 1], [0, 1]],
    ["positive height", [1, 1], [1, 0]],
  ])("checks %s independently", (_name, accepted, rejected) => {
    const valid = fixture(png(...accepted));
    expect(read(valid).equals(valid.data)).toBe(true);
    closed(valid);
    const invalid = fixture(png(...rejected));
    expect(() => read(invalid)).toThrow(/positive and at most 40 megapixels/);
    // Header read only: rejection must precede body allocation/read.
    expect(invalid.io.readSync).toHaveBeenCalledTimes(1);
    closed(invalid);
  });

  it("requires a regular opened handle, with size and header otherwise valid", () => {
    for (const regular of [true, false]) {
      const f = fixture();
      const stat = fs.statSync(f.path);
      f.io.fstatSync.mockImplementation(() => ({
        size: stat.size,
        mtimeMs: stat.mtimeMs,
        ctimeMs: stat.ctimeMs,
        isFile: () => regular,
      }));
      if (regular) expect(read(f).equals(f.data)).toBe(true);
      else {
        expect(() => read(f)).toThrow(/must be a regular file/);
        expect(f.io.readSync).not.toHaveBeenCalled();
      }
      closed(f);
    }
  });

  it("rejects a malformed header independently of the declared media type", () => {
    const valid = fixture();
    expect(read(valid).equals(valid.data)).toBe(true);
    closed(valid);
    const bytes = png();
    bytes[0] = 0;
    const invalid = fixture(bytes);
    expect(() => read(invalid)).toThrow(/Unsupported or malformed image header/);
    expect(invalid.io.readSync).toHaveBeenCalledTimes(1);
    closed(invalid);
  });

  it("checks the expected media type against an otherwise admissible PNG", () => {
    const valid = fixture();
    expect(read(valid, BYTE_LIMIT, "image/png").equals(valid.data)).toBe(true);
    closed(valid);
    const invalid = fixture();
    expect(() => read(invalid, BYTE_LIMIT, "image/jpeg")).toThrow(
      /extension does not match its file header/,
    );
    expect(invalid.io.readSync).toHaveBeenCalledTimes(1);
    closed(invalid);
  });

  it("admits dimensions ending at 1 MiB but not one byte past the header window", () => {
    const valid = fixture(jpegAtHeaderEnd(0));
    expect(read(valid, BYTE_LIMIT, "image/jpeg").equals(valid.data)).toBe(true);
    closed(valid);
    const invalid = fixture(jpegAtHeaderEnd(1));
    expect(() => read(invalid, BYTE_LIMIT, "image/jpeg")).toThrow(/first 1 MiB/);
    expect(invalid.io.readSync).toHaveBeenCalledTimes(1);
    expect(invalid.io.readSync.mock.calls[0][1].length).toBe(HEADER_LIMIT);
    closed(invalid);
  });
});

describe("independent same-handle image boundary regressions", () => {
  it("reads a small image through short descriptor reads and closes it", () => {
    const f = fixture();
    f.io.readSync.mockImplementation((fd, data, offset, length, position) =>
      fs.readSync(fd, data, offset, Math.min(length, 7), position),
    );
    const result = read(f);
    expect(Buffer.isBuffer(result)).toBe(true);
    expect(result.length).toBe(f.data.length);
    expect(result.equals(f.data)).toBe(true);
    closed(f);
  });

  it("pins the opened inode even when the pathname is replaced before reading", () => {
    for (const replaced of [false, true]) {
      const f = fixture();
      const replacement = png(2, 1);
      f.io.openSync.mockImplementation((...args) => {
        const fd = fs.openSync(...args);
        if (replaced) {
          fs.renameSync(f.path, `${f.path}.original`);
          fs.writeFileSync(f.path, replacement);
        }
        return fd;
      });
      const result = read(f);
      expect(result.equals(f.data)).toBe(true);
      expect(result.equals(replacement)).toBe(false);
      expect(fs.readFileSync(f.path).equals(replaced ? replacement : f.data)).toBe(true);
      closed(f);
    }
  });

  it("rejects same-size replacement between header admission and body read", () => {
    for (const replaced of [false, true]) {
      const f = fixture();
      beforeBody(f, () => {
        if (replaced) fs.writeFileSync(f.path, png(2, 1));
      });
      if (replaced) expect(() => read(f)).toThrow(/changed while being read/);
      else expect(read(f).equals(f.data)).toBe(true);
      // Both complete the body and second stat; only header bytes differ.
      expect(f.io.fstatSync).toHaveBeenCalledTimes(2);
      closed(f);
    }
  });

  it.each(["grow", "shrink"])("rejects %s during reading with bounded requests", (mode) => {
    for (const changed of [false, true]) {
      // A zero trailer keeps the header comparison equal even after shrinking:
      // the unread last byte in the zero-filled body buffer is also zero.
      const f = fixture(Buffer.concat([png(), Buffer.alloc(1)]));
      beforeBody(f, () => {
        if (changed) fs.truncateSync(f.path, f.data.length + (mode === "grow" ? 1 : -1));
      });
      if (changed) expect(() => read(f)).toThrow(/changed while being read/);
      else expect(read(f).equals(f.data)).toBe(true);
      // Metadata is fixed, so count (not a timestamp/size stat) rejects this.
      for (const [, buffer, , length] of f.io.readSync.mock.calls) {
        expect(buffer.length).toBeLessThanOrEqual(f.data.length + 1);
        expect(length).toBeLessThanOrEqual(f.data.length + 1);
      }
      expect(f.io.fstatSync).toHaveBeenCalledTimes(2);
      closed(f);
    }
  });

  it.each(["size", "mtimeMs", "ctimeMs"])("independently checks final %s", (field) => {
    for (const changed of [false, true]) {
      const f = fixture();
      const initial = fs.statSync(f.path);
      let calls = 0;
      f.io.fstatSync.mockImplementation(() => {
        calls++;
        return {
          isFile: () => true,
          size: initial.size,
          mtimeMs: initial.mtimeMs,
          ctimeMs: initial.ctimeMs,
          ...(changed && calls === 2 ? { [field]: initial[field] + 1 } : {}),
        };
      });
      if (changed) expect(() => read(f)).toThrow(/changed while being read/);
      else expect(read(f).equals(f.data)).toBe(true);
      expect(calls).toBe(2);
      closed(f);
    }
  });
});

